let LAST_REPORT = null;
ROUTES.reports = (p) => {
  const key = p[0] || 'overall'; const def = REPORTS.find(r => r[0] === key) || REPORTS[0];
  const rep = buildReport(def[0]); LAST_REPORT = { key: def[0], title: def[1], csv: rep.csv };
  const dated = ['incidents', 'capa'].includes(def[0]);
  const html = `<div class="no-print">${pageHead('Management reporting & assurance', 'Reports are generated live from the same records used across the system — filter by branch (sidebar selector) and date range, print, or export to CSV.', '', scopePill())}</div>
  <div class="grid" style="grid-template-columns:260px minmax(0,1fr)" id="repGrid">
    <div class="card no-print" style="align-self:start"><div class="card-body" style="padding:8px">${REPORTS.map(r => `<a class="nav-item" style="color:var(--grey-700)${r[0] === def[0] ? ';background:var(--blue-50);color:var(--blue);font-weight:650' : ''}" href="#/reports/${r[0]}">${esc(r[1])}</a>`).join('')}</div></div>
    <div class="card"><div class="card-head"><div><h2>${esc(def[1])}</h2><div class="ch-sub">${esc(rep.desc)}</div></div><div class="btn-row no-print"><button class="btn sm" data-act="repCsv">${icon('download', 'sm')} Export CSV</button><button class="btn sm primary" data-act="print">${icon('print', 'sm')} Print</button></div></div>
      <div class="print-only" style="padding:0 16px 8px"><b>${esc(orgOf(S.ui.org).name)}</b> — ${esc(scopeLabel())} — generated ${fmt(TODAY)}${dated ? ` — period ${fmt(REP.from)} to ${fmt(REP.to)}` : ''}. Demonstration data.</div>
      ${dated ? `<div class="toolbar no-print"><label class="muted">From</label><input type="date" id="repFrom" value="${REP.from}" style="padding:6px;border:1px solid var(--grey-300);border-radius:6px"><label class="muted">To</label><input type="date" id="repTo" value="${REP.to}" style="padding:6px;border:1px solid var(--grey-300);border-radius:6px"><button class="btn sm" data-act="repRange">Apply</button></div>` : ''}
      <div class="card-body" style="padding-top:12px">${rep.pre || ''}${rep.html}</div></div>
  </div>`;
  return { title: def[1], nav: 'reports', crumbs: [['Management reports', '#/reports'], [def[1], '#']], html, after: () => { if (window.innerWidth < 1024) document.getElementById('repGrid').style.gridTemplateColumns = 'minmax(0,1fr)'; } };
};
ACT.repRange = () => { const f = document.getElementById('repFrom').value, t = document.getElementById('repTo').value; if (!f || !t || f > t) { toast('Choose a valid date range.', 'error'); return; } REP.from = f; REP.to = t; rerender(); toast('Date range applied.'); };
ACT.repCsv = () => {
  if (!LAST_REPORT || !LAST_REPORT.csv.length) { toast('Nothing to export.', 'error'); return; }
  const csv = LAST_REPORT.csv.map(r => r.map(c => `"${String(c == null ? '' : c).replace(/"/g, '""')}"`).join(',')).join('\r\n');
  const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob);
  const a = document.createElement('a'); a.href = url; a.download = `VDW_${LAST_REPORT.key}_${S.ui.site}_${TODAY}.csv`; document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000);
  toast(`Exported ${LAST_REPORT.csv.length - 1} row(s) to CSV.`);
};

